 useEffect(()=>{viewRef.current={zoom,pan}},[zoom,pan]);
 useEffect(()=>{const canvas=canvasRef.current;if(!canvas||!image||page!=='workspace')return;const onWheel=(event:WheelEvent)=>{const rect=imgRef.current?.getBoundingClientRect();if(!rect||event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)return;event.preventDefault();wheelDelta.current+=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?100:1);const steps=Math.trunc(Math.abs(wheelDelta.current)/100);if(!steps)return;const direction=wheelDelta.current<0?1:-1;wheelDelta.current-=Math.sign(wheelDelta.current)*steps*100;const current=viewRef.current,nextZoom=Math.max(50,Math.min(300,current.zoom+direction*25*Math.min(steps,3)));if(nextZoom===current.zoom)return;const ratio=nextZoom/current.zoom,nextPan={x:current.pan.x+(event.clientX-(rect.left+rect.width/2))*(1-ratio),y:current.pan.y+(event.clientY-(rect.top+rect.height/2))*(1-ratio)};viewRef.current={zoom:nextZoom,pan:nextPan};setZoom(nextZoom);setPan(nextPan)};canvas.addEventListener('wheel',onWheel,{passive:false});return()=>{canvas.removeEventListener('wheel',onWheel);wheelDelta.current=0}},[image?.id,page]);

 useEffect(()=>{api<any>('/api/health').then(setSdk);api<Branding>('/api/settings/branding').then(setBranding).catch(()=>{});api<Inspection[]>('/api/inspections').then(async x=>{setInspections(x);if(!x[0])return;setInspectionId(x[0].id);const ims=await api<ImageRecord[]>(`/api/inspections/${x[0].id}/images`);if(ims[0])activateImage(ims[0])}).catch(e=>setError(e.message))},[]);
 useEffect(()=>{document.title=`${branding.application_title} — ${branding.application_subtitle}`;if(branding.application_logo_url){let icon=document.querySelector<HTMLLinkElement>('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.appendChild(icon)}icon.href=publicApiUrl(branding.application_logo_url)}},[branding]);
 useEffect(()=>{if(!analysis||analysis.status==='completed'||analysis.status==='failed')return;const t=setInterval(()=>api<Analysis>(`/api/analyses/${analysis.id}`).then(a=>{setAnalysis(a);if(a.status==='completed')api<Region[]>(`/api/analyses/${a.id}/regions`).then(setRegions)}),800);return()=>clearInterval(t)},[analysis]);
 useEffect(()=>{if(rangeMode!=='Manual'||analysis?.status!=='completed'){setRangeStats(undefined);return}let cancelled=false;const t=setTimeout(()=>{api<RangeStats>(`/api/analyses/${analysis.id}/range-stats?minimum_c=${rangeMin}&maximum_c=${rangeMax}`).then(result=>{if(!cancelled)setRangeStats(result)}).catch(e=>{if(!cancelled)setError(e.message)})},180);return()=>{cancelled=true;clearTimeout(t)}},[analysis?.id,analysis?.status,rangeMode,rangeMin,rangeMax,regions]);
 useEffect(()=>{if(tool!=='spot'||analysis?.status!=='completed'||!spot)return;let cancelled=false;const {x,y}=spot;const t=setTimeout(()=>{api<{temperature_c:number|null;valid:boolean}>(`/api/analyses/${analysis.id}/pixels/${x}/${y}`).then(v=>{if(!cancelled)setSpot({x,y,...v})}).catch(()=>{if(!cancelled)setSpot({x,y,temperature_c:null,valid:false})})},35);return()=>{cancelled=true;clearTimeout(t)}},[tool,analysis?.id,analysis?.status,spot?.x,spot?.y]);
 useEffect(()=>{const shortcuts=(e:KeyboardEvent)=>{const target=e.target as HTMLElement|null;if(target?.matches('input, textarea, select, [contenteditable="true"]'))return;if(e.key==='Escape')setSelected(undefined);else if(e.key==='5'){e.preventDefault();setTool('line-temperature')}};window.addEventListener('keydown',shortcuts);return()=>window.removeEventListener('keydown',shortcuts)},[]);

 const activateImage=(im:ImageRecord)=>{activeImageId.current=im.id;savedWorkspaceFingerprint.current=null;setHydratedImageId(undefined);setImage(im);setImageDetails(undefined);setZoom(100);setPan({x:0,y:0});setAnalysis(im.latest_analysis);setRegions([]);setSelected(undefined);setProbes([]);setNotes([]);setSelectedNoteId(undefined);setDrawings([]);setSelectedDrawingId(undefined);setDraftDrawing(null);drawingGesture.current=null;const detailRequest=api<ImageDetails>(`/api/images/${im.id}/details`).then(details=>{if(activeImageId.current===im.id)setImageDetails(details)}).catch(e=>setError(e.message));const workspaceRequest=api<any>(`/api/images/${im.id}/workspace`).then(value=>{if(activeImageId.current!==im.id)return;setProbes(value.probes||[]);setRangeMode(value.range_mode||'Auto');setRangeMin(value.range_min??-20);setRangeMax(value.range_max??150);if(value.temperature_visibility)temperatureVisibility.replace(value.temperature_visibility)}).catch(()=>{});const drawingRequest=api<ImageDrawing[]>(`/api/images/${im.id}/drawings`).then(items=>{if(activeImageId.current===im.id){drawingsRef.current=items;setDrawings(items)}}).catch(e=>setError(e.message));const noteRequest=api<ImageNote[]>(`/api/images/${im.id}/capture-note`,{method:'POST'}).then(items=>{if(activeImageId.current===im.id){notesRef.current=items;setNotes(items)}}).catch(e=>setError(e.message));const regionRequest=im.latest_analysis?.status==='completed'?api<Region[]>(`/api/analyses/${im.latest_analysis.id}/regions`).then(items=>{if(activeImageId.current===im.id)setRegions(items)}):Promise.resolve();void Promise.allSettled([detailRequest,workspaceRequest,drawingRequest,noteRequest,regionRequest]).then(()=>{if(activeImageId.current===im.id)setHydratedImageId(im.id)})};
 const createNoteAt=async(x:number,y:number)=>{if(!image)return;try{const note=await api<ImageNote>(`/api/images/${image.id}/notes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:'New note',x:Math.max(0,Math.min(.7,x)),y:Math.max(0,Math.min(.75,y)),font:'sans',font_size:16,color:'yellow'})});notesRef.current=[...notesRef.current,note];setNotes(notesRef.current);setSelectedNoteId(note.id);setSelected(undefined);setSelectedDrawingId(undefined);setTool('select')}catch(e:any){setError(e.message)}};
 const saveNote=async(id:string)=>{const note=notesRef.current.find(n=>n.id===id);if(!note||!image)return;try{await api<ImageNote>(`/api/images/${image.id}/notes/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(note)})}catch(e:any){setError(e.message)}};
 const changeNote=(id:string,patch:Partial<ImageNote>,persist=false)=>{notesRef.current=notesRef.current.map(n=>n.id===id?{...n,...patch}:n);setNotes(notesRef.current);if(persist)void saveNote(id)};
 const removeNote=async(id:string)=>{if(!image)return;try{await api<void>(`/api/images/${image.id}/notes/${id}`,{method:'DELETE'});notesRef.current=notesRef.current.filter(n=>n.id!==id);setNotes(notesRef.current);setSelectedNoteId(undefined)}catch(e:any){setError(e.message)}};
 const createDrawing=async(draft:DrawingDraft)=>{if(!image)return;try{const created=await api<ImageDrawing>(`/api/images/${image.id}/drawings`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft)});drawingsRef.current=[...drawingsRef.current,created];setDrawings(drawingsRef.current);setSelectedDrawingId(created.id);setSelected(undefined);setSelectedNoteId(undefined);remember(async()=>{await api<void>(`/api/images/${image.id}/drawings/${created.id}`,{method:'DELETE'});drawingsRef.current=drawingsRef.current.filter(d=>d.id!==created.id);setDrawings(drawingsRef.current);setSelectedDrawingId(undefined)})}catch(e:any){setError(e.message)}};
 const removeDrawing=async(id:string)=>{if(!image)return;try{const removed=drawingsRef.current.find(d=>d.id===id);await api<void>(`/api/images/${image.id}/drawings/${id}`,{method:'DELETE'});drawingsRef.current=drawingsRef.current.filter(d=>d.id!==id);setDrawings(drawingsRef.current);setSelectedDrawingId(undefined);if(removed)remember(async()=>{const restored=await api<ImageDrawing>(`/api/images/${image.id}/drawings`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...removed,id:undefined})});drawingsRef.current=[...drawingsRef.current,restored];setDrawings(drawingsRef.current)})}catch(e:any){setError(e.message)}};
 const setDrawingControl=(id:string,control:DrawingPoint|null)=>{drawingsRef.current=drawingsRef.current.map(d=>d.id===id?{...d,control}:d);setDrawings(drawingsRef.current)};
 const bendDrawing=(id:string,event:React.PointerEvent)=>setDrawingControl(id,normalizedPoint(event));
 const moveDrawingEndpoint=(id:string,index:0|1,event:React.PointerEvent)=>{const point=normalizedPoint(event);drawingsRef.current=drawingsRef.current.map(d=>d.id===id?{...d,points:d.points.map((p,i)=>i===index?point:p)}:d);setDrawings(drawingsRef.current)};
 const moveDrawing=(id:string,event:React.PointerEvent)=>{const imageElement=imgRef.current;if(!imageElement)return;const rect=imageElement.getBoundingClientRect();const current=drawingsRef.current.find(d=>d.id===id);if(!current)return;const previous=drawingMove.current;if(!previous||previous.id!==id){drawingMove.current={id,x:event.clientX,y:event.clientY,points:current.points.map(p=>({...p})),control:current.control};return}const dx=(event.clientX-previous.x)/rect.width,dy=(event.clientY-previous.y)/rect.height;const shift=(p:DrawingPoint)=>({x:Math.max(0,Math.min(1,p.x+dx)),y:Math.max(0,Math.min(1,p.y+dy))});const next=drawingsRef.current.map(d=>d.id===id?{...d,points:previous.points.map(shift),control:previous.control?shift(previous.control):previous.control}:d);drawingMove.current={...previous,x:event.clientX,y:event.clientY,points:next.find(d=>d.id===id)!.points,control:next.find(d=>d.id===id)!.control};drawingsRef.current=next;setDrawings(next)};
 const saveDrawing=async(id:string)=>{if(!image)return;const updated=drawingsRef.current.find(d=>d.id===id);if(!updated)return;try{await api<ImageDrawing>(`/api/images/${image.id}/drawings/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(updated)})}catch(e:any){setError(e.message)}};
 const editArrow=(id:string,event:React.MouseEvent)=>{const drawing=drawingsRef.current.find(d=>d.id===id);const canvas=canvasRef.current;if(!drawing||drawing.kind!=='arrow'||!canvas)return;const rect=canvas.getBoundingClientRect();setSelectedDrawingId(id);setSelected(undefined);setSelectedNoteId(undefined);setArrowStyle({id,color:drawing.color,stroke_width:drawing.stroke_width,x:Math.max(8,Math.min(rect.width-230,event.clientX-rect.left+12)),y:Math.max(8,Math.min(rect.height-190,event.clientY-rect.top+12))})};
 const saveArrowStyle=async()=>{if(!arrowStyle||!image)return;const previous=drawingsRef.current.find(d=>d.id===arrowStyle.id);if(!previous)return;const updated={...previous,color:arrowStyle.color,stroke_width:arrowStyle.stroke_width};try{await api<ImageDrawing>(`/api/images/${image.id}/drawings/${updated.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(updated)});drawingsRef.current=drawingsRef.current.map(d=>d.id===updated.id?updated:d);setDrawings(drawingsRef.current);setArrowStyle(null);remember(async()=>{await api<ImageDrawing>(`/api/images/${image.id}/drawings/${previous.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(previous)});drawingsRef.current=drawingsRef.current.map(d=>d.id===previous.id?previous:d);setDrawings(drawingsRef.current)})}catch(e:any){setError(e.message)}};
 const makeInspection=async()=>{const tower=prompt('Tower ID','TWR-001');if(!tower)return;const x=await api<any>('/api/inspections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tower_code:tower})});setInspectionId(x.id);setInspections(v=>[x,...v]);setPage('upload')};
 const upload=async(files:FileList|null)=>{if(!files?.length)return;setBusy(true);setError('');try{let id=inspectionId;if(!id){const x=await api<any>('/api/inspections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tower_code:`TWR-${new Date().toISOString().slice(0,10)}`})});id=x.id;setInspectionId(id)}for(const file of Array.from(files)){const form=new FormData();form.append('file',file);const isPackage=file.name.toLowerCase().endsWith('.thermalpkg');const im=await api<ImageRecord>(`/api/inspections/${id}/${isPackage?'packages':'images'}`,{method:'POST',body:form});activateImage(im);setPage('workspace');if(!isPackage&&sdk?.decoder_available){const a=await api<Analysis>(`/api/images/${im.id}/analyses`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{"parameters":{}}'});setAnalysis(a)}}}catch(e:any){setError(e.message)}finally{setBusy(false)}};
 const nativePoint=(e:React.PointerEvent):Point=>{const el=imgRef.current!,r=el.getBoundingClientRect(),w=analysis?.width||640,h=analysis?.height||512;return{x:Math.max(0,Math.min(w-1,Math.floor((e.clientX-r.left)/r.width*w))),y:Math.max(0,Math.min(h-1,Math.floor((e.clientY-r.top)/r.height*h)))}};
 const normalizedPoint=(e:React.PointerEvent)=>{const r=imgRef.current!.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}};
 const measure=async(p:Point)=>{if(!analysis)return;const v=await api<any>(`/api/analyses/${analysis.id}/pixels/${p.x}/${p.y}`);const within_window=v.temperature_c!=null&&(rangeMode==='Auto'||v.temperature_c>=rangeMin&&v.temperature_c<=rangeMax);setHover(`${p.x}, ${p.y} · ${v.temperature_c==null?'invalid':f(v.temperature_c)}${v.valid&&!within_window?' · outside selected range':''}`);return {...v,within_window}};
 const pointerMove=(e:React.PointerEvent)=>{const drag=panDrag.current;if(drag?.pointerId===e.pointerId){const dx=e.clientX-drag.clientX,dy=e.clientY-drag.clientY;if(Math.hypot(dx,dy)>3)drag.moved=true;setPan({x:drag.x+dx,y:drag.y+dy});return}const gesture=drawingGesture.current;if(gesture?.pointerId===e.pointerId){const p=normalizedPoint(e),last=gesture.points.at(-1)!;if(gesture.kind==='freehand'){if(gesture.points.length<1000&&Math.hypot(p.x-last.x,p.y-last.y)>.002)gesture.points.push(p)}else gesture.points[1]=p;setDraftDrawing({kind:gesture.kind,points:[...gesture.points],color:'#ff7b2b',stroke_width:4});return}if(!analysis||analysis.status!=='completed')return;const p=nativePoint(e);if(drawing.current?.pointerId===e.pointerId){drawing.current.end=p;setDragEnd(p)}else if(tool==='spot')setSpot(previous=>previous?.x===p.x&&previous?.y===p.y?previous:p);else if(tool==='select')setHover('Select or drag a box')};
 const pointerDown=async(e:React.PointerEvent)=>{if(e.button!==0)return;if(tool==='bend-arrow'&&selectedDrawingId){setDrawingControl(selectedDrawingId,normalizedPoint(e));void saveDrawing(selectedDrawingId);setTool('select');return}const kind=drawingKind(tool);if(kind&&image){const p=normalizedPoint(e);drawingGesture.current={pointerId:e.pointerId,kind,points:[p,p]};setDraftDrawing({kind,points:[p,p],color:'#ff7b2b',stroke_width:4});e.currentTarget.setPointerCapture(e.pointerId);setSelectedDrawingId(undefined);return}if(tool==='note'&&image){const p=normalizedPoint(e);await createNoteAt(p.x,p.y);return}if(tool==='select'&&zoom>100){e.currentTarget.setPointerCapture(e.pointerId);panDrag.current={pointerId:e.pointerId,clientX:e.clientX,clientY:e.clientY,x:pan.x,y:pan.y,moved:false};return}if(!analysis||analysis.status!=='completed')return;const p=nativePoint(e);if(tool==='spot')return;if(tool==='select'){setSelected(undefined);setSelectedNoteId(undefined);setSelectedDrawingId(undefined);return}if(tool==='point'){const v=await measure(p);if(v?.valid&&v?.within_window){const before=[...probes];remember(()=>setProbes(before));setProbes(x=>[...x,{...p,temperature_c:v.temperature_c}])}return}if(tool==='rectangle'||tool==='circle'||tool==='line-temperature'){const regionKind=tool==='line-temperature'?'line':tool;drawing.current={pointerId:e.pointerId,start:p,end:p,kind:regionKind};e.currentTarget.setPointerCapture(e.pointerId);setDragStart(p);setDragEnd(p)}};
