 const saveRegionSize=async(id:number)=>{const region=regionsRef.current.find(r=>r.id===id);if(!region)return;try{const updated=await api<Region>(`/api/regions/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:region.name,kind:region.kind,points:region.points,is_reference:region.is_reference,minimum_point:region.minimum_selection?{x:region.minimum_selection.x,y:region.minimum_selection.y}:null})});setRegions(items=>items.map(r=>r.id===id?{...r,statistics:updated.statistics,minimum_selection:updated.minimum_selection}:r))}catch(e:any){setError(e.message)}};
 const rotateRegion=async(id:number,targetDegrees:number)=>{const region=regions.find(r=>r.id===id);if(!region||region.kind==='circle')return;let points=region.points;if(region.kind==='rectangle'){const [a,b]=points;points=[{x:Math.min(a.x,b.x),y:Math.min(a.y,b.y)},{x:Math.max(a.x,b.x),y:Math.min(a.y,b.y)},{x:Math.max(a.x,b.x),y:Math.max(a.y,b.y)},{x:Math.min(a.x,b.x),y:Math.max(a.y,b.y)}]}const center={x:points.reduce((s,p)=>s+p.x,0)/points.length,y:points.reduce((s,p)=>s+p.y,0)/points.length};const current=Math.atan2(points[1].y-points[0].y,points[1].x-points[0].x),delta=targetDegrees*Math.PI/180-current,cs=Math.cos(delta),sn=Math.sin(delta),maxX=(analysis?.width||640)-1,maxY=(analysis?.height||512)-1;const rotated=points.map(p=>({x:Math.max(0,Math.min(maxX,Math.round(center.x+(p.x-center.x)*cs-(p.y-center.y)*sn))),y:Math.max(0,Math.min(maxY,Math.round(center.y+(p.x-center.x)*sn+(p.y-center.y)*cs)))}));try{const old={...region,points:region.points.map(p=>({...p}))};const updated=await api<Region>(`/api/regions/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:region.name,kind:'polygon',points:rotated,is_reference:region.is_reference})});remember(async()=>{const restored=await api<Region>(`/api/regions/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:old.name,kind:old.kind,points:old.points,is_reference:old.is_reference,minimum_point:old.minimum_selection?{x:old.minimum_selection.x,y:old.minimum_selection.y}:null})});setRegions(items=>items.map(r=>r.id===id?{...old,statistics:restored.statistics,minimum_selection:restored.minimum_selection}:r))});setRegions(items=>items.map(r=>r.id===id?{...r,kind:'polygon',points:rotated,statistics:updated.statistics,minimum_selection:updated.minimum_selection}:r))}catch(e:any){setError(e.message)}};
