 const moveRegionLive=(id:number,dx:number,dy:number)=>{const next=regionsRef.current.map(r=>{if(r.id!==id)return r;const points=translatedPoints(r,dx,dy),sx=points[0].x-r.points[0].x,sy=points[0].y-r.points[0].y;return {...r,points,minimum_selection:r.minimum_selection?{...r.minimum_selection,x:r.minimum_selection.x+sx,y:r.minimum_selection.y+sy}:r.minimum_selection}});regionsRef.current=next;setRegions(next)};
